from collections import defaultdict
from typing import List

class Solution:
    def subdomainVisits(self, cpdomains: List[str]) -> List[str]:
        counts = defaultdict(int)
        for cp in cpdomains:
            count_str, domain = cp.split()
            count = int(count_str)
            parts = domain.split('.')
            for i in range(len(parts)):
                subdomain = ".".join(parts[i:])
                counts[subdomain] += count
        return [f"{count} {sub}" for sub, count in counts.items()]

class Solution {
public:
    vector<string> subdomainVisits(vector<string>& cpdomains) {
        unordered_map<string, int> counts;
        for (const string& cp : cpdomains) {
            int space = cp.find(' ');
            int count = stoi(cp.substr(0, space));
            string domain = cp.substr(space + 1);
            counts[domain] += count;
            for (int i = 0; i < (int)domain.length(); i++) {
                if (domain[i] == '.') {
                    counts[domain.substr(i + 1)] += count;
                }
            }
        }
        vector<string> res;
        for (const auto& [sub, count] : counts) {
            res.push_back(to_string(count) + " " + sub);
        }
        return res;
    }
};

class Solution {
    public List<String> subdomainVisits(String[] cpdomains) {
        Map<String, Integer> counts = new HashMap<>();
        for (String cp : cpdomains) {
            String[] parts = cp.split(" ");
            int count = Integer.parseInt(parts[0]);
            String domain = parts[1];
            counts.put(domain, counts.getOrDefault(domain, 0) + count);
            for (int i = 0; i < domain.length(); i++) {
                if (domain.charAt(i) == '.') {
                    String sub = domain.substring(i + 1);
                    counts.put(sub, counts.getOrDefault(sub, 0) + count);
                }
            }
        }
        List<String> res = new ArrayList<>();
        for (Map.Entry<String, Integer> e : counts.entrySet()) {
            res.add(e.getValue() + " " + e.getKey());
        }
        return res;
    }
}

var subdomainVisits = function(cpdomains) {
    const counts = new Map();
    for (const cp of cpdomains) {
        const [countStr, domain] = cp.split(' ');
        const count = Number(countStr);
        const parts = domain.split('.');
        for (let i = 0; i < parts.length; i++) {
            const sub = parts.slice(i).join('.');
            counts.set(sub, (counts.get(sub) || 0) + count);
        }
    }
    const res = [];
    for (const [sub, count] of counts.entries()) {
        res.push(`${count} ${sub}`);
    }
    return res;
};
